package com.johnny.hotel.group;
import com.johnny.hotel.booking.deposit.DepositService;import com.johnny.hotel.entity.*;import com.johnny.hotel.enums.*;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.guest.*;import com.johnny.hotel.mapper.*;import com.johnny.hotel.pagination.*;import com.johnny.hotel.reservation.*;import com.johnny.hotel.service.*;import lombok.RequiredArgsConstructor;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.math.*;import java.time.*;import java.time.temporal.*;import java.util.*;
@Service@RequiredArgsConstructor public class GroupReservationService{private final GroupMapper db;private final ReservationAccess access;private final PaginationSupport pages;private final RoomTypeCapacityGuard capacity;private final BookingMapper bookings;private final BookingPricingService pricing;private final BookingPriceVersionMapper versions;private final BookingNightlyRateMapper nightly;private final ReservationPolicyService policies;private final DepositService deposits;private final GuestService guests;private final SysAuditLogMapper audits;@Value("${hotel.currency}")private String hotelCurrency;
 private void require(boolean x,String m){if(!x)throw new BusinessException(m);}private boolean manager(ReservationAccess.Actor a){return a.roles().stream().anyMatch(Set.of("MANAGER","OWNER","SUPER_ADMIN")::contains);}private ReservationAccess.Actor reader(){return access.policyReader();}private void audit(Long actor,String action,String detail){require(audits.insert(SysAuditLog.builder().operatorId(actor).action(action).detail(detail).build())==1,"Audit write failed");}
 @Transactional public GroupModels.Group create(GroupRequests.Create r){var a=access.actor();require(manager(a),"Group management access denied");require(r.getArrivalDate().isBefore(r.getDepartureDate()),"Invalid group dates");var x=GroupModels.Group.builder().groupCode(r.getGroupCode().trim()).groupName(r.getGroupName().trim()).groupType(r.getGroupType()).status(0).organizerName(r.getOrganizerName()).contactPhone(r.getContactPhone()).contactEmail(r.getContactEmail()).arAccountId(r.getArAccountId()).arrivalDate(r.getArrivalDate()).departureDate(r.getDepartureDate()).currency(r.getCurrency()).bookingSource(r.getBookingSource()).billingMode("INDIVIDUAL_PAY").notes(r.getNotes()).createdBy(a.id()).build();db.insertGroup(x);audit(a.id(),"GROUP_CREATE","Group "+x.getId());return db.group(x.getId());}
 @Transactional public GroupModels.Block addBlock(Long group,GroupRequests.Block r){var a=access.actor();require(manager(a),"Group management access denied");var g=db.lockGroup(group);require(g!=null&&(g.getStatus()==0||g.getStatus()==1),"Group blocks are not editable");require(r.getStartDate().isBefore(r.getEndDate())&&!r.getStartDate().isBefore(g.getArrivalDate())&&!r.getEndDate().isAfter(g.getDepartureDate()),"Invalid block dates");require(Set.of("STANDARD_DYNAMIC","NEGOTIATED_RATE").contains(r.getRateMode()),"Invalid rate mode");require(!"NEGOTIATED_RATE".equals(r.getRateMode())||r.getNegotiatedRate()!=null&&r.getNegotiatedRate().scale()<=2&&r.getNegotiatedRate().signum()>0,"Invalid negotiated rate");capacity.requireBlockCapacity(r.getRoomTypeId(),r.getStartDate(),r.getEndDate(),r.getQuantity());var b=GroupModels.Block.builder().groupId(group).roomTypeId(r.getRoomTypeId()).startDate(r.getStartDate()).endDate(r.getEndDate()).blockedQuantity(r.getQuantity()).pickedUpQuantity(0).releasedQuantity(0).rateMode(r.getRateMode()).negotiatedRate(r.getNegotiatedRate()).cutOffDate(r.getCutOffDate()).status(1).build();db.insertBlock(b);audit(a.id(),"GROUP_BLOCK_CREATE","Group "+group+" block "+b.getId());return db.block(b.getId());}
 @Transactional public GroupModels.Group confirm(Long id){var a=access.actor();require(manager(a),"Group management access denied");var blocks=db.blocks(id);require(!blocks.isEmpty(),"Group requires a room block");var current=db.lockGroup(id);if(current!=null&&current.getStatus()==2)return current;require(current!=null&&current.getStatus()==0,"Group cannot be confirmed");require("INDIVIDUAL_PAY".equals(current.getBillingMode()),"Group billing mode is not supported");for(var b:blocks)capacity.requireBlockCapacity(b.getRoomTypeId(),b.getStartDate(),b.getEndDate(),b.getBlockedQuantity()-b.getReleasedQuantity());require(db.transition(id,0,2)==1,"Group changed concurrently");audit(a.id(),"GROUP_CONFIRM","Group "+id);return db.group(id);}
 @Transactional public GroupModels.Block release(Long id,int q){var a=access.actor();require(manager(a),"Group management access denied");var b=db.lockBlock(id);require(b!=null,"Block not found");capacity.lockAndRead(b.getRoomTypeId(),b.getStartDate(),b.getEndDate());require(db.release(id,q)==1,"Release exceeds remaining block");audit(a.id(),"GROUP_BLOCK_RELEASE","Block "+id+" quantity "+q);return db.block(id);}
 @Transactional public GroupModels.Block cutoff(Long id){var a=access.actor();require(manager(a),"Group management access denied");var b=db.lockBlock(id);require(b!=null&&b.getCutOffDate()!=null&&!LocalDate.now().isBefore(b.getCutOffDate()),"Cutoff is not due");int remaining=b.remaining();if(remaining>0)db.release(id,remaining);audit(a.id(),"GROUP_BLOCK_CUTOFF_RELEASE","Block "+id+" quantity "+remaining);return db.block(id);}
 @Transactional public GroupModels.Group cancel(Long id){var a=access.actor();require(manager(a),"Group management access denied");var g=db.lockGroup(id);require(g!=null,"Group not found");if(g.getStatus()==3)return g;require(g.getStatus()!=4,"Completed group cannot be cancelled");for(var b:db.blocks(id)){capacity.lockAndRead(b.getRoomTypeId(),b.getStartDate(),b.getEndDate());int remaining=b.remaining();if(remaining>0)require(db.release(b.getId(),remaining)==1,"Block changed concurrently");}require(db.transition(id,g.getStatus(),3)==1,"Group changed concurrently");audit(a.id(),"GROUP_CANCEL","Group "+id);return db.group(id);}
 @Transactional public GroupModels.Entry addEntry(Long group,GroupRequests.Entry r){access.hotel();var g=db.lockGroup(group);var b=db.lockBlock(r.getBlockId());require(g!=null&&b!=null&&b.getGroupId().equals(group)&&g.getStatus()!=3&&g.getStatus()!=4,"Invalid group block");if(r.getGuestProfileId()!=null)guests.get(r.getGuestProfileId(),access.actor().id());var prior=db.entryByKey(r.getRequestKey());if(prior!=null)return prior;var e=GroupModels.Entry.builder().groupId(group).blockId(b.getId()).guestProfileId(r.getGuestProfileId()).requestKey(r.getRequestKey()).status(r.getGuestProfileId()==null?0:1).build();db.insertEntry(e);audit(access.actor().id(),"GROUP_ROOMING_CREATE","Group "+group+" entry "+e.getId());return db.entryByKey(r.getRequestKey());}
 @Transactional public GroupModels.Entry attach(Long id,Long guest){var a=access.hotel();var e=db.lockEntry(id);require(e!=null&&e.getBookingId()==null,"Rooming entry cannot be changed");if(guest!=null)guests.get(guest,a.id());require(db.attach(id,guest)==1,"Rooming entry changed concurrently");audit(a.id(),"GROUP_ROOMING_GUEST_CHANGE","Entry "+id);return db.lockEntry(id);}
 @Transactional(isolation=Isolation.READ_COMMITTED)public GroupModels.Entry pickup(Long id){var a=access.hotel();var e=db.lockEntry(id);require(e!=null,"Rooming entry not found");if(e.getBookingId()!=null)return e;require(e.getGuestProfileId()!=null,"Rooming guest is required before pickup");var b=db.lockBlock(e.getBlockId());var g=db.lockGroup(e.getGroupId());require(g!=null&&g.getStatus()==2&&b!=null&&b.getStatus()==1,"Group is not eligible for pickup");require("INDIVIDUAL_PAY".equals(g.getBillingMode()),"Group billing mode is not supported");capacity.lockAndRead(b.getRoomTypeId(),b.getStartDate(),b.getEndDate());require(db.pickup(b.getId())==1,"No remaining group room");var policy=policies.activeForBooking(true);var booking=Booking.builder().bookerGuestProfileId(e.getGuestProfileId()).createdByUserId(a.id()).roomTypeId(b.getRoomTypeId()).reservationSource("GROUP").reservationPolicyId(policy.getId()).groupId(g.getId()).groupBlockId(b.getId()).guestCount(1).checkInDate(b.getStartDate()).checkOutDate(b.getEndDate()).status(BookingStatus.PENDING.getCode()).totalPrice(BigDecimal.ZERO).build();bookings.insert(booking);if("NEGOTIATED_RATE".equals(b.getRateMode()))negotiated(booking,b,a.id());else pricing.createFullRepriceVersion(booking.getId(),b.getRoomTypeId(),"GROUP_PICKUP","Group accepted quote",a.id());deposits.openForReservation(booking.getId());if(e.getGuestProfileId()!=null)guests.addToBooking(booking.getId(),GuestRequests.Add.builder().guestId(e.getGuestProfileId()).role(GuestRole.PRIMARY).build(),a.id());require(db.bindBooking(e.getId(),booking.getId())==1,"Rooming entry changed concurrently");audit(a.id(),"GROUP_PICKUP","Entry "+id+" booking "+booking.getId());return db.lockEntry(id);}
 private void negotiated(Booking b,GroupModels.Block block,Long actor){int nights=Math.toIntExact(ChronoUnit.DAYS.between(b.getCheckInDate(),b.getCheckOutDate()));BigDecimal total=block.getNegotiatedRate().multiply(BigDecimal.valueOf(nights)).setScale(2);var v=BookingPriceVersion.builder().bookingId(b.getId()).versionNo(1).changeType("GROUP_NEGOTIATED_RATE").reason("Group block "+block.getId()).isActive(1).totalPrice(total).currency(hotelCurrency).createdBy(actor).build();versions.insert(v);for(LocalDate d=b.getCheckInDate();d.isBefore(b.getCheckOutDate());d=d.plusDays(1))nightly.insert(BookingNightlyRate.builder().priceVersionId(v.getId()).bookingId(b.getId()).stayDate(d).roomTypeId(b.getRoomTypeId()).rateAmount(block.getNegotiatedRate()).rateSource("GROUP_NEGOTIATED").build());bookings.updateTotalPrice(b.getId(),total);}
 public GroupModels.Group get(Long id){reader();var x=db.group(id);require(x!=null,"Group not found");return x;}public List<GroupModels.Block> blocks(Long id){get(id);return db.blocks(id);}public PageResult<GroupModels.Entry> entries(Long id,Integer status,Long block,Integer p,Integer s){get(id);var w=pages.window(p,s,status!=null||block!=null);int z=pages.limit(w);return pages.result(w,z==0?List.of():db.entries(id,status,block,w.offset(),z),db.countEntries(id,status,block));}public PageResult<Booking> children(Long id,Integer status,Integer p,Integer s){get(id);var w=pages.window(p,s,status!=null);int z=pages.limit(w);return pages.result(w,z==0?List.of():db.childBookings(id,status,w.offset(),z),db.countChildBookings(id,status));}public PageResult<GroupModels.Group> page(Integer status,String q,Integer p,Integer s){reader();q=q==null||q.isBlank()?null:q.trim();var w=pages.window(p,s,status!=null||q!=null);int z=pages.limit(w);return pages.result(w,z==0?List.of():db.page(status,q,w.offset(),z),db.count(status,q));}}




